from collections import Counter
from typing import List

#O(n)
def findAnagrams(s: str, p: str) -> List[int]:
    len_s, len_p = len(s), len(p)
    if len_s < len_p:
        return []

    result = []
    p_count = Counter(p)          # count of characters in p
    window_count = Counter(s[:len_p])  # count for the first window

    if window_count == p_count:
        result.append(0)

    for i in range(len_p, len_s):
        start_char = s[i - len_p]  # char leaving the window
        end_char = s[i]            # char entering the window
        
        # Remove the start_char from the window count
        window_count[start_char] -= 1
        if window_count[start_char] == 0:
            del window_count[start_char]

        # Add the new char to the window
        window_count[end_char] += 1

        # Compare counts
        if window_count == p_count:
            result.append(i - len_p + 1)

    return result


s = "" \
""
p = ""
print(findAnagrams(s, p))